package org.brightstats.model;
import java.util.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
/** Shared live/vector geometry; statistical bindings remain untouched. */
public final class DiagramGeometry {
    private DiagramGeometry(){}
    public record Point(double x,double y){public Point plus(double dx,double dy){return new Point(x+dx,y+dy);}}
    public record Size(double width,double height,boolean ellipse){}
    public record Bounds(double x,double y,double width,double height){}
    public static Size size(Node node){if(node.type()==ElementType.DONGLE)return new Size(10,10,true);if(node.type()==ElementType.CBSEM_ERROR_TERM)return new Size(38,38,true);if(node.type()==ElementType.GAUSSIAN_COPULA||node.type()==ElementType.QUADRATIC_EFFECT||node.type()==ElementType.PROCESS_MODEL_QUADRATIC_EFFECT)return new Size(50,50,true);if(node.type()==ElementType.REGRESSION_INTERCEPT)return new Size(48,48,false);return node.type().observed()?new Size(128,44,false):new Size(150,76,true);}
    public static Point position(Document document,String id){return position(document,id,new HashMap<>());}
    private static Point position(Document document,String id,Map<String,Point> cache){if(cache.containsKey(id))return cache.get(id);Node node=document.node(id);Point result;if(node.type()==ElementType.DONGLE&&node.properties().has("edge")){var edge=document.link(DiagramModels.string(node.properties(),"edge",null));var endpoints=endpoints(document,edge);Point a=position(document,endpoints[0],cache),b=position(document,endpoints[1],cache);double fraction=node.properties().has("fraction")?DiagramModels.number(node.properties().get("fraction"),"anchor fraction"):.5;if(fraction<0||fraction>1)throw new IllegalArgumentException("Anchor fraction must be between zero and one.");result=new Point(a.x+(b.x-a.x)*fraction+node.x(),a.y+(b.y-a.y)*fraction+node.y());}else result=new Point(node.x(),node.y());cache.put(id,result);return result;}
    public static List<Point> path(Document document,Link link){String[] endpoints=endpoints(document,link);Point a=position(document,endpoints[0]),b=position(document,endpoints[1]);List<Point> points=new ArrayList<>();points.add(a);if(link.type().covariance()){double dx=b.x-a.x,dy=b.y-a.y;points.add(new Point((a.x+b.x)/2-.18*dy,(a.y+b.y)/2+.18*dx));}else{document.nodes().stream().filter(node->node.type()==ElementType.DONGLE&&node.properties().has("edge")&&node.properties().get("edge").getAsString().equals(link.id())).sorted(Comparator.comparingDouble(node->node.properties().has("fraction")?node.properties().get("fraction").getAsDouble():.5)).forEach(node->points.add(position(document,node.id())));}points.add(b);if(points.size()>1){points.set(0,boundary(a,points.get(1),size(document.node(endpoints[0]))));points.set(points.size()-1,boundary(b,points.get(points.size()-2),size(document.node(endpoints[1]))));}return List.copyOf(points);}
    private static String[] endpoints(Document document,Link link){String source=link.source(),target=link.target();if(link.type().measurement()&&document.family()!=Family.CBSEM){Node a=document.node(source),b=document.node(target),component=a.type().latent()?a:b,observed=component==a?b:a;boolean loading=document.family()!=Family.PROCESS&&DiagramModels.bool(link.properties(),"loading",!DiagramModels.string(component.properties(),"measurementType","REFLECTIVE").equals("FORMATIVE"));source=loading?component.id():observed.id();target=loading?observed.id():component.id();}if(link.type()==ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INDEPENDENT_VARIABLE||link.type()==ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INTERCEPT){Node a=document.node(source);if(a.type()==ElementType.REGRESSION_DEPENDENT_VARIABLE){String swap=source;source=target;target=swap;}}return new String[]{source,target};}
    private static Point boundary(Point center,Point toward,Size size){double dx=toward.x-center.x,dy=toward.y-center.y;if(dx==0&&dy==0)return center;double halfX=size.width/2,halfY=size.height/2;double scale=size.ellipse?1/Math.sqrt(dx*dx/(halfX*halfX)+dy*dy/(halfY*halfY)):Math.min(dx==0?Double.POSITIVE_INFINITY:halfX/Math.abs(dx),dy==0?Double.POSITIVE_INFINITY:halfY/Math.abs(dy));return center.plus(dx*scale,dy*scale);}
    public static Point annotation(Document document,Annotation note){if(note.attachment().isEmpty())return new Point(note.x(),note.y());if(document.nodes().stream().anyMatch(node->node.id().equals(note.attachment())))return position(document,note.attachment()).plus(note.x(),note.y());List<Point> path=path(document,document.link(note.attachment()));Point a=path.getFirst(),b=path.getLast();if(path.size()==3&&document.link(note.attachment()).type().covariance()){Point c=path.get(1);return new Point(.25*a.x+.5*c.x+.25*b.x,.25*a.y+.5*c.y+.25*b.y).plus(note.x(),note.y());}return new Point((a.x+b.x)/2,(a.y+b.y)/2).plus(note.x(),note.y());}
    public static Bounds bounds(Document document){double minX=0,minY=0,maxX=1000,maxY=700;for(var node:document.nodes())if(node.type()!=ElementType.ROOT){Point p=position(document,node.id());Size size=size(node);minX=Math.min(minX,p.x-size.width/2-20);minY=Math.min(minY,p.y-size.height/2-20);maxX=Math.max(maxX,p.x+size.width/2+20);maxY=Math.max(maxY,p.y+size.height/2+20);}for(var note:document.annotations()){Point p=annotation(document,note);minX=Math.min(minX,p.x-10);minY=Math.min(minY,p.y-10);maxX=Math.max(maxX,p.x+note.width()+10);maxY=Math.max(maxY,p.y+note.height()+10);}for(var link:document.links())for(var point:path(document,link)){minX=Math.min(minX,point.x-20);minY=Math.min(minY,point.y-20);maxX=Math.max(maxX,point.x+20);maxY=Math.max(maxY,point.y+20);}return new Bounds(minX,minY,maxX-minX,maxY-minY);}
}
